db = SessionLocal()

for item in original_data:
    existing_item = db.query(models.Item).filter(models.Item.item_id == item["id"]).first()
    
    if not existing_item:
        new_item = models.Item(
            item_id=item["id"],
            subsystem=item["category"],
            component_name=item["name"],
            purpose=item["purpose"],
            qty=item["qty"],
            unit_cost=item["unit"],
            supplier_link=item["url"],
            cost_basis=item["basis"],
            stage=item["stage"]
        )
        db.add(new_item)

db.commit()
db.close()
print("Successfully seeded all original parts into plm.db!")